  'Жалдаушы жалдау ақысын кешіктірді': { ru: 'Арендатор задержал оплату', en: 'The tenant is late with rent' },
  'RENTSAFE логотипі': { ru: 'Логотип RENTSAFE', en: 'RENTSAFE logo' },
  'Жалдау шарты': { ru: 'Договор аренды', en: 'Rental agreement' },
  'Дайын': { ru: 'Готово', en: 'Ready' },
