const textNodes = new WeakMap();
const originalAttributes = new WeakMap();

export function getLanguage() {
  const saved = localStorage.getItem(LANGUAGE_KEY);
  return supportedLanguages.includes(saved) ? saved : 'kk';
}

export function tr(value) {
  const language = getLanguage();
  if (language === 'kk' || typeof value !== 'string') return value;
  return copy[value]?.[language] || value;
}

export function applyLanguage(language) {
  const nextLanguage = supportedLanguages.includes(language) ? language : 'kk';
  localStorage.setItem(LANGUAGE_KEY, nextLanguage);
  document.documentElement.lang = nextLanguage;

  const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
  while (walker.nextNode()) {
    const node = walker.currentNode;
    if (!textNodes.has(node)) textNodes.set(node, node.nodeValue);
    const original = textNodes.get(node).replace(/\s+/g, ' ').trim();
    if (!original) continue;
    node.nodeValue = tr(original);
  }

  document.querySelectorAll('[placeholder], [aria-label], [alt], [title], [data-title], [data-text]').forEach((element) => {
    let originals = originalAttributes.get(element);
    if (!originals) {
      originals = {};
      for (const name of ['placeholder', 'aria-label', 'alt', 'title', 'data-title', 'data-text']) {
        if (element.hasAttribute(name)) originals[name] = element.getAttribute(name);
      }
      originalAttributes.set(element, originals);
    }
    for (const [name, value] of Object.entries(originals)) {
      element.setAttribute(name, tr(value));
    }
  });

  const languageSelect = document.getElementById('language-select');
  if (languageSelect) languageSelect.value = nextLanguage;
  window.dispatchEvent(new CustomEvent('rentsafe:languagechange', { detail: { language: nextLanguage } }));
}

export function initLanguageSelector() {
  const selector = document.getElementById('language-select');
  if (selector) {
    selector.addEventListener('change', () => applyLanguage(selector.value));
  }
  applyLanguage(getLanguage());
}
